-- ISSUE-HYGIENE-4 (2026-10-26, pillar autonomy; follows hygiene-1 to -3): 13 open agent_issues closed with evidence that two independent measurements agreed on.
--
-- HOW THE LIST WAS MADE (read-only against live qnfo-audit, the repository and the fleet's hosts, 2026-10-26)
--   2026-10-26: 192 open agent_issues measured against live state by 17 classifier agents (12 issues per agent, SELECT-only, read of D1, the repository and the fleet's hosts); 17 closes proposed, 13 confirmed by independent skeptics (eight skeptic agents re-measured from scratch, four high-priority closes by two), 4 refuted and left open (100404, 100577, 1000015, 1000148)
--   Each issue was measured by one agent against its own definition of done, and every proposed close was then re-measured from scratch by skeptics told to refute it
--   and to default to refuted (two skeptics, different lenses, both had to confirm for a critical or high issue; one for the rest). Issues linked to a session, under a live
--   work claim or with a code task in flight were not touched. A close that rests on a duplicate names the OPEN successor that carries the work. Nothing is closed as wontfix
--   and no metric target was changed. The evidence of each issue is the text below, standalone and dated.
--
-- MECHANISM (as hygiene-1): issue_fold_ledger keeps the before-state of every row, the contracts leave the closing path, the close names its channel
--   (workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26), the evidence goes into issue_triage and the live trigger triage_close_sync_issue_upd closes the issue; no trigger is added.
--   Rows written: issue_fold_ledger 13, then at most 13 issue closes with their lifecycle rows. No DELETE, no DROP.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE issue_triage SET triage_state = (SELECT f.triage_state FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), close_evidence = (SELECT f.triage_close_evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), reopened_count = (SELECT f.triage_reopened_count FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), triaged_at = (SELECT f.triage_triaged_at FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26' AND applied = 1); UPDATE agent_issues SET status = 'open', close_channel = (SELECT f.agent_close_channel FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE id IN (SELECT issue_id FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26' AND applied = 1) AND status = 'closed' AND close_channel = 'workflow:ISSUE-HYGIENE-1 session-sweep-2026-10-26'; UPDATE remediation_contracts SET status = (SELECT f.contract_status FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1), last_verdict = (SELECT f.contract_last_verdict FROM issue_fold_ledger f WHERE f.contract_class = remediation_contracts.class AND f.rule = 'session-sweep-2026-10-26' AND f.applied = 1 ORDER BY f.id DESC LIMIT 1) WHERE class IN (SELECT contract_class FROM issue_fold_ledger WHERE rule = 'session-sweep-2026-10-26' AND applied = 1 AND contract_class IS NOT NULL) AND last_verdict LIKE 'superseded:closure-superseded%'

-- 1. The ledger rows: each carries the before-state and the evidence
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 2957 AS id, 'superseded by 1798 (METRIC-TRIGGER-362-OPEN-AGENT-ISSUES: Autonomy gap: more than 20 open agent issues): both open on open_agent_issues (418 open, trigger 362 gt 260 hit=1, 7d mean 280.9 vs prior 177.6, measured 2026-10-26 09:20Z); 1798 is open, unclaimed and carries the drain; /improvement finding covered_by equals its title exactly (IL-DEFECT-ONLY-1).' AS ev, 1798 AS succ UNION ALL SELECT 100350 AS id, 'moot: the 20,000-char restore refusal is gone by another route: living-paper trg_papers_pub_floor_upd3 now reads MIN-PAPER-LENGTH-4 (migration_runs 563 ok 2026-10-26T07:08:12Z; qnfo-2025-* exempt, reinstated papers need 8000), all 13 short retracted owner papers read status published with no banner at 09:25Z, and the issue-100274 probe reads 0/0 (remediation_verifications 316916, 09:16:09Z).' AS ev, NULL AS succ UNION ALL SELECT 100382 AS id, 'superseded by 100392 (CODE-LOOP-EXHAUSTED-1: ct_206b76jubryohp qnfo-fleet-control/worker.js): same root 100355, file and SyntaxError; ct_32n3q37l31e9h5 and its retries ct_f238j30jb2tpbt, ct_206b76jubryohp all failed, none queued; 100392 and 100355 open and unclaimed, code-probe text absent on origin/main 3cd2570 (count 0, 2026-10-26).' AS ev, 100392 AS succ UNION ALL SELECT 100450 AS id, 'verified: on 2026-10-26 09:24Z qnfo-audit cron_fire_log holds 26 qnfo-gateway rows, all ok, hourly from 2026-10-25T09:00:44Z to 09:00:44Z today (newest 23 min old against the 90-minute DoD) and unbroken across 46 later deploys, and cron_fault_seen worker-silent:qnfo-gateway has cleared_at 2026-10-25T09:06:51Z with no uncleared gateway fault.' AS ev, NULL AS succ UNION ALL SELECT 100466 AS id, 'verified: PR #3493 merged 2026-10-21T14:58:33Z; its 12 live workers have ok fleet_deploys rows 2026-10-21 15:09-15:51Z (errata-hub, errata-publish, errata-respond, research-radar FOLDED and impact RETIRED, none in the account); on 2026-10-26 a worker-code scan of all 36 account scripts finds 0 ''zenodo'' matches; deploy_drift_cf 32 sync.' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 100498 AS id, 'moot: the floor conflict ct_im100350 targeted is resolved by migration 2026-10-26-publish-floor-reinstate.sql (migration_runs 563 ok 2026-10-26T07:08Z); the 07:11Z notice-repair restored the two refused papers (blocked=[]), all 13 owner papers list on papers.qnfo.org at 09:20Z, issue-100274''s probe reads 0/0 pass (316916, 09:16Z), and root 100350 is moot on the same evidence.' AS ev, NULL AS succ UNION ALL SELECT 100519 AS id, 'verified: the fleet already uses createAI and no live worker uses the deprecated packages: on 2026-10-26 live qnfo-agents 0.2.2 (agents.qnfo.org/health, agents@0.30.1) calls createAI from agents/models/ai-sdk (main src/index.ts lines 28, 247); workers-ai-provider and ai-gateway-provider are imported by no worker on origin/main nor in any live script scanned; only RETIRED qnfo-artifact-agent vendor and the FOLDED fleet-advisor lockfile name them.' AS ev, NULL AS succ UNION ALL SELECT 100588 AS id, 'superseded by 1000002 (Integration chain Errata watch -> respond -> publish backpressured, open, unclaimed): same chain breach and ceiling (pending <= 10); measured 2026-10-26 09:22Z in qnfo-observability /integration: errata n=684 draining, consumer advanced 0m ago (errata_queue 522 internal-open + 132 detected + 30 audited), so this ticket adds no separate work.' AS ev, 1000002 AS succ UNION ALL SELECT 100589 AS id, 'moot: measured 2026-10-26 09:21Z: fleet.qnfo.org/api/state error_workers=[] (analytics_error null, err24 12), so no worker has errors in the last 3h after its current deploy; qnfo-code-orchestrator (last error 06:57Z, deploy ok 08:46:59Z) reads recovered; residual errors stay tracked by open 1000079 and 1000233.' AS ev, NULL AS succ UNION ALL SELECT 1000030 AS id, 'moot: measured 2026-10-26 09:22Z: GitHub lists none of the three named refs; branch_hygiene_log has delete ''contained in main'' 2026-10-24T21:00Z and archive-delete 2026-10-25T15:01Z; bhDecide on main (same on 8c35b1f, before filing) already deletes ahead_by 0 branches after 6h grace; all 21 remaining non-main refs have ahead>=1 and tips under 22h old; the second defect stays with open 1000018.' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);
INSERT INTO issue_fold_ledger (issue_id, rule, successor_id, evidence, agent_status, agent_updated_at, agent_close_channel, triage_state, triage_close_evidence, triage_reopened_count, triage_triaged_at, contract_class, contract_status, contract_last_verdict, contract_last_attempt_at) SELECT m.id, 'session-sweep-2026-10-26', v.succ, v.ev || ' ISSUE-HYGIENE-1 ' || strftime('%Y-%m-%d', 'now'), m.status, m.updated_at, m.close_channel, t.triage_state, t.close_evidence, t.reopened_count, t.triaged_at, c.class, c.status, c.last_verdict, c.last_attempt_at FROM (SELECT 1000064 AS id, 'superseded by 1000002 (Integration chain Errata watch -> respond -> publish backpressured, open): same chain and drain condition (pending <= 10); measured 2026-10-26 09:22Z: n=684 draining, advanced 0m ago, 67 errata_queue rows moved in 3h, so the no-progress premise is false. Blocker host: errata-hub folded into qnfo-research-exec (tick hub 1.8.1-folded; errata-fold.test.mjs 16 passed), owner qnfo-research-exec.' AS ev, 1000002 AS succ UNION ALL SELECT 1000185 AS id, 'verified: on 2026-10-26 qnfo-audit holds program-manager:QNFO.OPS, RSCH, INFRA, REACH and PERSONAL beside portfolio-manager (persona_briefs tick 08:00Z has 6 rows; fleet_runs management-personas ok at 07:36Z and 08:36Z); persona_actions show 59 decisions in 24h; fleet.qnfo.org/api/managers returns 5 programs. Placement: fleet_tasks workflow plus dashboard beside the portfolio manager, not qnfo-ops (which holds no portfolio code either).' AS ev, NULL AS succ UNION ALL SELECT 1000242 AS id, 'moot: ct_im1000179 (failed, 9 attempts, no PR) cannot publish because main already carries its goal: #4130 (d5005730, merged 2026-10-25T17:20Z, before the task was created 17:36Z) added the 405 contract and rt-api.test.mjs G3; on 2026-10-26 GET https://fleet.qnfo.org/api/cmd returns 405, Allow: POST, body error=method_not_allowed, path, allow, hint (dashboard 1.69.2 live, deploy_drift_cf sync).' AS ev, NULL AS succ) v JOIN agent_issues m ON m.id = v.id JOIN issue_triage t ON t.issue_id = m.id LEFT JOIN remediation_contracts c ON c.class = 'issue-' || m.id WHERE m.status = 'open' AND NOT EXISTS (SELECT 1 FROM issue_fold_ledger f WHERE f.issue_id = m.id AND f.applied = 0);

-- 2. Settle the contracts, name the channel, close through the triage row, mark the ledger
UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:closure-superseded (ISSUE-HYGIENE-1)', last_attempt_at = datetime('now') WHERE class IN (SELECT f.contract_class FROM issue_fold_ledger f WHERE f.applied = 0 AND f.contract_class IS NOT NULL) AND status IN ('monitoring', 'escalated', 'active', 'holding', 'needs-machine-probe', 'probe-review-refused');
UPDATE agent_issues SET close_channel = 'workflow:ISSUE-HYGIENE-1 ' || (SELECT f.rule FROM issue_fold_ledger f WHERE f.issue_id = agent_issues.id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE status = 'open' AND id IN (SELECT issue_id FROM issue_fold_ledger WHERE applied = 0);
UPDATE issue_triage SET triage_state = 'closed', triaged_at = datetime('now'), close_evidence = (SELECT f.evidence FROM issue_fold_ledger f WHERE f.issue_id = issue_triage.issue_id AND f.applied = 0 ORDER BY f.id DESC LIMIT 1) WHERE issue_id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN agent_issues a ON a.id = f.issue_id WHERE f.applied = 0 AND a.status = 'open');
UPDATE agent_issues SET status = 'closed', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000 WHERE status = 'open' AND id IN (SELECT f.issue_id FROM issue_fold_ledger f JOIN issue_triage t ON t.issue_id = f.issue_id WHERE f.applied = 0 AND t.triage_state = 'closed' AND t.close_evidence = f.evidence);
UPDATE issue_fold_ledger SET applied = 1, applied_at = datetime('now') WHERE applied = 0 AND (SELECT a.status FROM agent_issues a WHERE a.id = issue_fold_ledger.issue_id) <> 'open';
